// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != address(0));
        vm.prank(c.owner());
        c.transferOwnership(caller);
        vm.prank(caller);
        try c.transferOwnership(newOwner) {} catch { 
            assertTrue(c.owner() != address(0));
            return;
        }
        assertTrue(c.owner() != address(0));
    }
}
